# recursively find inputs whose name or arg contains kwd or dbkey
def walk(x,path=''):
    if isinstance(x,dict):
        if 'name' in x:
            nm=x.get('name'); arg=x.get('argument'); typ=x.get('type')
            if 'kwd' in str(nm).lower() or 'dbkey' in str(arg).lower() or 'dbkey' in str(nm).lower() or typ in ('drill_down',):
                print(path, nm, typ, x.get('value'))
        for k,v in x.items():
            walk(v,path+'/'+str(k))
    elif isinstance(x,list):
        for i,v in enumerate(x): walk(v,path+f'/{i}')
walk(d)
print('help contains kwd?', 'kwd' in json.dumps(d).lower())
PY"

